svg.script:
var W = 1400, all = document.querySelectorAll('g.f');
function fit(g, w) {
  var t = g.querySelector('text'), n = g.getAttribute('data-n');
  var room = Math.floor((w - 6) / 6.6);
  t.textContent = n.length <= room ? n : (room > 3 ? n.slice(0, room - 2) + '..' : '');
}
function zoom(g0) {
  var x0 = +g0.getAttribute('data-x'), w0 = +g0.getAttribute('data-w'), d0 = +g0.getAttribute('data-d');
  all.forEach(function (g) {
    var x = +g.getAttribute('data-x'), w = +g.getAttribute('data-w'), d = +g.getAttribute('data-d');
    var r = g.querySelector('rect'), t = g.querySelector('text');
    var inside = x >= x0 - 1e-6 && x + w <= x0 + w0 + 1e-6, below = d < d0 && x <= x0 && x + w >= x0 + w0;
    if (inside || below) {
      var nx = below ? 0 : (x - x0) / w0 * (W - 20), nw = below ? W - 20 : w / w0 * (W - 20);
      r.setAttribute('x', 10 + nx); r.setAttribute('width', Math.max(nw - 1, 0.5));
      t.setAttribute('x', 13 + nx); g.style.display = ''; fit(g, nw);
      g.style.opacity = below && d < d0 ? 0.6 : 1;
    } else { g.style.display = 'none'; }
  });
}
all.forEach(function (g) { g.addEventListener('click', function () { zoom(g); }); });
document.getElementById('reset').addEventListener('click', function () { zoom(all[0]); });
